// grammar_rocq.c — hand-authored tree-sitter TSLanguage for Rocq.
//
// Original work. Unlike the other vendored grammars, this is NOT generated by
// the tree-sitter CLI from a grammar.js — there are no parse/lex tables here.
// Our pure-C parser builds the TSTree directly (see rocq/rocq_tree.*), so the
// runtime never runs a table-driven parse; it only *walks* the tree. Walking
// needs just the symbol names/metadata and field maps, which we provide here.
// The node-type/field/production ids come from rocq/rocq_cst.h.
#include "rocq/rocq_cst.h"
#include "rocq/rocq_tree.h"
#include "tree_sitter/api.h" // must precede parser.h: parser.h skips TSLanguageMetadata if api.h seen
#include "parser.h" // tree-sitter runtime: TSLanguage, TSSymbolMetadata, TSFieldMapEntry, TSMapSlice
#include "length.h"
#include "subtree.h"
#include "tree.h"
#include "array.h"

#include <stdbool.h>
#include <stdlib.h>

