// Alias map: none (one entry per symbol, all zero = no aliases).
static const TSSymbol rocq_alias_map[1] = {0};

// Alias sequences: we use no child aliases, but a TSTreeCursor reads
// alias_sequences[production_id * max_alias_sequence_length + child_index] for
// every visited child, so this must be a valid (zero) array large enough for the
// field-bearing productions' bounded child counts. Variable-arity nodes use
// production 0 (RPROD_NONE), for which the lookup short-circuits to 0.
enum { ROCQ_MAX_ALIAS_SEQ_LEN = 3 };
static const TSSymbol rocq_alias_sequences[RPROD_COUNT * ROCQ_MAX_ALIAS_SEQ_LEN] = {0};

// Field names, indexed by RocqField (index 0 unused).
static const char *const rocq_field_names[RFLD_COUNT] = {
    [RFLD_NONE] = (void *)0,
    [RFLD_NAME] = "name",
    [RFLD_TYPE] = "type",
    [RFLD_BODY] = "body",
    [RFLD_CLASS] = "class",
    [RFLD_PATTERN] = "pattern",
};

// Field-map entries, grouped by production and sorted by field id within each.
// Entries within each production's slice MUST be sorted by field_id ascending
// (the runtime narrows the slice by field_id). child_index is the structural
// index of the field's child within the node.
static const TSFieldMapEntry rocq_field_map_entries[] = {
    // RPROD_NAME (index 0, len 1)
    {RFLD_NAME, 0, false},
    // RPROD_NAME_TYPE (index 1, len 2): NAME(3) < TYPE(5)
    {RFLD_NAME, 0, false},
    {RFLD_TYPE, 1, false},
    // RPROD_INSTANCE (index 3, len 2): CLASS(2) < NAME(3)
    {RFLD_CLASS, 1, false},
    {RFLD_NAME, 0, false},
    // RPROD_NOTATION (index 5, len 1)
    {RFLD_PATTERN, 0, false},
};

