const TSLanguage *tree_sitter_rocq(void) { return &rocq_language; }

// ── Tree builder ──────────────────────────────────────────────────────────
// Constructs a real tree-sitter TSTree from the parser's open/leaf/close calls.

typedef struct {
    TSSymbol sym;
    uint32_t prod;
    SubtreeArray children;
} RocqFrame;

struct RocqTreeBuilder {
    const char *src;
    uint32_t len;
    uint32_t cursor; // byte offset consumed so far (token starts compute padding from here)
    SubtreePool pool;
    RocqFrame *frames;
    int nframes;
    int cap;
};

// tree-sitter Length for [from,to): bytes + extent (rows = newlines, column =
// bytes after the last newline, in bytes).
static Length rocq_span(const char *src, uint32_t from, uint32_t to) {
    Length l;
    l.bytes = to - from;
    uint32_t rows = 0;
    uint32_t last_nl_end = from;
    for (uint32_t i = from; i < to; i++) {
        if (src[i] == '\n') {
            rows++;
            last_nl_end = i + 1;
        }
    }
    l.extent.row = rows;
    l.extent.column = rows ? (to - last_nl_end) : (to - from);
    return l;
}

static void rocq_tb_push_frame(RocqTreeBuilder *b, TSSymbol sym, uint32_t prod) {
    if (b->nframes >= b->cap) {
        int nc = b->cap ? b->cap * 2 : 16;
        RocqFrame *nf = (RocqFrame *)realloc(b->frames, (size_t)nc * sizeof(*nf));
        if (!nf) {
            return;
        }
        b->frames = nf;
        b->cap = nc;
    }
    RocqFrame f = {.sym = sym, .prod = prod}; // children zero-inits to an empty Array
    b->frames[b->nframes++] = f;
}

RocqTreeBuilder *rocq_tb_new(const char *source, int source_len) {
    RocqTreeBuilder *b = (RocqTreeBuilder *)calloc(1, sizeof(*b));
    if (!b) {
        return NULL;
    }
    b->src = source;
    b->len = source_len > 0 ? (uint32_t)source_len : 0;
    b->cursor = 0;
    // Open the implicit root frame before creating the subtree pool: if its
    // allocation fails (OOM) we bail here, before any ts_runtime allocation.
    rocq_tb_push_frame(b, RSYM_SOURCE_FILE, RPROD_NONE);
    if (b->nframes == 0) {
        free(b->frames);
        free(b);
        return NULL;
    }
    b->pool = ts_subtree_pool_new(64);
    return b;
}

// Precondition (guaranteed by the parser, the sole caller): the builder is valid
// with the root frame open, and leaves arrive in non-decreasing byte order with
// end_byte >= start_byte. No defensive validation is performed.
void rocq_tb_leaf(RocqTreeBuilder *b, RocqSymbol sym, uint32_t start_byte, uint32_t end_byte) {
    Length padding = rocq_span(b->src, b->cursor, start_byte);
    Length size = rocq_span(b->src, start_byte, end_byte);
    Subtree leaf = ts_subtree_new_leaf(&b->pool, (TSSymbol)sym, padding, size, 0, 0, false, false,
                                       false, &rocq_language);
    array_push(&b->frames[b->nframes - 1].children, leaf);
    b->cursor = end_byte;
}

void rocq_tb_open(RocqTreeBuilder *b, RocqSymbol sym, RocqProduction prod) {
    rocq_tb_push_frame(b, (TSSymbol)sym, (uint32_t)prod);
}

void rocq_tb_close(RocqTreeBuilder *b) {
    if (b->nframes <= 1) {
        // Nothing to close but the implicit root — e.g. an `End.` with no open
        // module/section, which the parser dispatches unconditionally.
        return;
    }
    RocqFrame f = b->frames[--b->nframes];
    if (f.children.size == 0) {
        // Drop empty nodes (e.g. a `term`/`proof` that captured no tokens) rather
        // than emit a zero-width named node. An empty frame never grew its children
        // array (size 0 ⇒ no array_push ⇒ contents NULL), so there is nothing to free.
        return;
    }
    MutableSubtree node = ts_subtree_new_node((TSSymbol)f.sym, &f.children, f.prod, &rocq_language);
    array_push(&b->frames[b->nframes - 1].children, ts_subtree_from_mut(node));
}

void *rocq_tb_finish(RocqTreeBuilder *b) {
    while (b->nframes > 1) { // close any unbalanced open nodes (e.g. unterminated module)
        rocq_tb_close(b);
    }
    RocqFrame f = b->frames[0];
    b->nframes = 0;
    MutableSubtree root = ts_subtree_new_node((TSSymbol)f.sym, &f.children, f.prod, &rocq_language);
    // Pass tree-sitter's default whole-document included range (as ts_parser
    // does) rather than NULL/0 — ts_tree_new memcpy's the ranges unconditionally,
    // and a NULL source trips the runtime's nonnull contract.
    static const TSRange full_range = {
        .start_point = {0, 0},
        .end_point = {0xFFFFFFFFu, 0xFFFFFFFFu},
        .start_byte = 0,
        .end_byte = 0xFFFFFFFFu,
    };
    TSTree *tree = ts_tree_new(ts_subtree_from_mut(root), &rocq_language, &full_range, 1);
    return tree;
}

void rocq_tb_free(RocqTreeBuilder *b) {
    ts_subtree_pool_delete(&b->pool);
    free(b->frames);
    free(b);
}

void rocq_tree_free(void *tree) {
    if (tree) {
        ts_tree_delete((TSTree *)tree);
    }
}
